import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart'; import '../../../../shared/providers/auth_provider.dart'; import '../../../surplus/presentation/screens/surplus_screen.dart';
class AdminDashboard extends ConsumerWidget{const AdminDashboard({super.key});@override Widget build(BuildContext c,WidgetRef ref){final u=ref.watch(authProvider).user;return Scaffold(appBar:AppBar(title:const Text('Admin Dashboard'),actions:[IconButton(onPressed:()async{await ref.read(authProvider.notifier).logout();if(c.mounted)c.go('/login');},icon:const Icon(Icons.logout))]),body:ListView(padding:const EdgeInsets.all(20),children:[Text('Welcome ${u?.name??'Administrator'}',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:20),Card(child:ListTile(title:const Text('Market & Surplus'),subtitle:const Text('Monitor supply, demand and international activation'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const SurplusScreen()))),),const Card(child:ListTile(title:Text('System Administration'),subtitle:Text('User and platform administration endpoints can be connected here.')))]));}}
